/**
 * Skill Template Workflow Modules
 *
 * This file is generated by splitting the legacy monolithic
 * templates file into workflow-focused modules.
 */
import type { SkillTemplate, CommandTemplate } from '../types.js';
import { optionalWorkflow } from '../optional-workflow.js';
import { STORE_SELECTION_GUIDANCE } from './store-selection.js';
import { PROJECT_ROOT_GUARD } from './project-root.js';

const APPLY_HANDOFF = optionalWorkflow(
  'apply',
  'suggest `/opsx:apply` to carry the delta into code',
  'say that the code may need updating and offer to carry the delta into it'
);

const APPLY_NEXT_STEP = optionalWorkflow(
  'apply',
  'Recommended next command: `/opsx:apply <change-id>`',
  'Recommended next step: update the implementation separately in the codebase'
);

export function getFixChangeSkillTemplate(): SkillTemplate {
  return {
    name: 'openspec-fix-change',
    description: 'Fix an active OpenSpec change by updating its existing planning artifacts, scope, and follow-up tasks without creating a new proposal. Use when the user needs to correct a bug, UI issue, logic flaw, missing behavior, integration problem, or performance regression in an existing change. Also use when the user says "openspec fix" or "opsx fix". Never edits application source code.',
    instructions: `Fix an active OpenSpec change in place and keep it coherent. Never edit implementation code.

${STORE_SELECTION_GUIDANCE}

${PROJECT_ROOT_GUARD}

**Input**: Optionally specify a change name after \`/opsx:fix\` or \`openspec fix\`. If omitted, infer it from the current conversation. If it is ambiguous, ask the user to choose from the active changes.

**Steps**

1. **Select the active change**
   - If a name is provided, use it.
   - Otherwise, infer the change from the current thread.
   - If only one active change exists, select it automatically.
   - If multiple active changes match, list the most recent ones and ask the user to pick one.
   - Never create a new change folder as a fallback.
   - Never modify archived changes.

2. **Verify the target and read only the relevant artifacts**
   - Confirm the change exists and is still active.
   - Use \`openspec status --change "<name>" --json\` to confirm the change root and artifact state.
   - Read only the artifacts that are relevant to the issue: proposal, affected spec(s), design, tasks, and the relevant implementation files required for impact analysis.
   - Do not scan the entire repository unless the issue clearly requires it.
   - If the issue is a bug or a regression, read the affected implementation and the specific requirement/spec sections before editing any artifact.

3. **Understand the requested fix and classify it**
   - Classify the issue as one of: bug correction, UI correction, logic correction, missing functionality, integration correction, or performance correction.
   - Summarize the problem in one sentence, then identify the impacted requirements, design decisions, and implementation files.
   - Keep the analysis concise and scoped. Do not broaden the task or edit unrelated artifacts.

4. **Create a unique fix ID and record the change**
   - Use sequential IDs in this form: \`FIX-001\`, \`FIX-002\`, \`FIX-003\`.
   - Inspect existing fix history before choosing the next ID so you do not repeat a value.
   - Add a fix record containing: fix ID, title, problem description, reason, impacted requirements, affected components, affected artifacts, and status.
   - Record it in the active change's existing proposal history and keep the original proposal intact.
   - Do not delete earlier history entries.

5. **Update only the impacted artifacts**
   - Append the fix log to the existing \`proposal.md\` while preserving the original proposal text.
   - Update only the affected requirement blocks in the relevant specification files; preserve unchanged requirements.
   - Do not duplicate scenarios or repeat unchanged acceptance criteria.
   - Update \`design.md\` only when the fix changes architecture or design intent.
   - Add new tasks to \`tasks.md\` under the matching fix ID and keep all completed tasks intact.
   - Preserve all completed work, do not duplicate existing tasks, and mark obsolete tasks as superseded rather than deleting their history.
   - Use the existing OpenSpec task syntax so the apply workflow can recognize the new tasks.
   - Do not create additional documents unless the schema or workflow specifically requires them.

6. **Stop before implementation**
   - This workflow is planning and artifact update only; it must not modify application source code.
   - It must not silently execute implementation tasks or create a new change folder.
   - After updating the artifacts, show:
     - Fix ID
     - Problem identified
     - Affected artifacts
     - New pending tasks
     - ${APPLY_NEXT_STEP}

**Output**

After completing the workflow, report:
- The selected change and fix ID
- The concise impact summary
- The exact artifacts that were updated
- The pending fix tasks
- The recommended next step: ${APPLY_HANDOFF}

**Guardrails**
- Never create another proposal or change folder when fixing an existing change.
- Never edit archived changes.
- Never change unrelated requirements or design decisions.
- Never add duplicate tasks or IDs.
- Never pretend the fix is implemented; update only the artifacts and stop before code changes.
- Keep the fix minimal and scoped to the active change.
- Preserve history and completed tasks while adding the new fix work.
- If the user request is ambiguous, ask which matching change they mean before editing anything.`,
    license: 'MIT',
    compatibility: 'Requires openspec CLI.',
    metadata: { author: 'openspec', version: '1.0' },
  };
}

export function getOpsxFixCommandTemplate(): CommandTemplate {
  return {
    name: 'OPSX: Fix',
    description: 'Fix an active change without creating a new proposal (Experimental)',
    category: 'Workflow',
    tags: ['workflow', 'artifacts', 'experimental'],
    content: `Fix an active OpenSpec change in place and keep it coherent. Never edit implementation code.

${STORE_SELECTION_GUIDANCE}

${PROJECT_ROOT_GUARD}

**Input**: Optionally specify a change name after \`/opsx:fix\` or \`/opsx:fix <name>\`. If omitted, infer it from the current conversation. If it is ambiguous, ask the user to choose from the active changes.

**Steps**

1. **Select the active change**
   - If a name is provided, use it.
   - Otherwise, infer it from context.
   - If only one active change exists, select it automatically.
   - If multiple active changes match, ask the user to choose one.
   - Never create a new change folder as a fallback.
   - Never modify archived changes.

2. **Inspect only the relevant artifacts**
   - Confirm the change exists and is active.
   - Run \`openspec status --change "<name>" --json\` to confirm state.
   - Read the proposal, affected spec, design, tasks, and only the implementation files directly related to the issue.
   - Keep the impact analysis narrow and concise.

3. **Classify the issue**
   - Classify it as a bug, UI, logic, missing functionality, integration, or performance correction.
   - Summarize the issue and identify impacted requirements, artifacts, and files.

4. **Create the fix ID**
   - Use sequential IDs such as \`FIX-001\`, \`FIX-002\`, and \`FIX-003\`.
   - Check existing fix history first so you do not reuse an ID.
   - Record the fix title, reason, affected components, affected artifacts, and status.

5. **Update the active change in place**
   - Append a fix summary to \`proposal.md\` without deleting the original proposal text.
   - Update only the affected requirements in the relevant specification files.
   - Update \`design.md\` only if the fix changes architecture or design decisions.
   - Append new tasks under the fix ID in \`tasks.md\` while keeping completed tasks intact.
   - Preserve all completed work and do not duplicate tasks.
   - Mark obsolete tasks as superseded rather than deleting the history.

6. **Stop before implementation**
   - This workflow is planning-only. It must not edit app code or execute implementation tasks.
   - After updating the artifacts, summarize:
     - Fix ID
     - Problem identified
     - Affected artifacts
     - New pending tasks
     - ${APPLY_NEXT_STEP}

**Guardrails**
- Never create a new proposal or duplicate change folder.
- Never touch archived changes.
- Never modify unrelated requirements or design decisions.
- Never duplicate tasks or fix IDs.
- Never pretend the code is implemented; stop after the plan and task update.
- Keep the fix narrow and do not broaden the scope.

Use the existing OpenSpec change structure and task syntax so the standard ${APPLY_HANDOFF} flow can pick up the newly added fix tasks.`,
    license: 'MIT',
    compatibility: 'Requires openspec CLI.',
    metadata: { author: 'openspec', version: '1.0' },
  };
}
